/* Lesson data: Bellman-Ford (structure mode). Steps are generated by simulating the algorithm. */
(function () {
  function build(names, pos, edges, order) {
    /* edges: [from, to, w]; order: edge indexes in the order they are processed */
    var kindOf = {}, used = {};
    var ops = [];
    names.forEach(function (n, i) { ops.push(['node', 'v' + i, n, pos[i][0], pos[i][1], 'circle']); });
    edges.forEach(function (e, k) {
      used[e[0]] = (used[e[0]] || 0) + 1;
      kindOf[k] = 'e' + used[e[0]];
      ops.push(['edge', 'v' + e[0], 'v' + e[1], kindOf[k]]);
      var mx = Math.round((pos[e[0]][0] + pos[e[1]][0]) / 2), my = Math.round((pos[e[0]][1] + pos[e[1]][1]) / 2);
      ops.push(['node', 'w' + k, String(e[2]), mx, my, 'cell'], ['tag', 'w' + k, 'dim']);
    });
    return { ops: ops, kindOf: kindOf };
  }
  function run(names, pos, edges, order, rounds, cyc) {
    var g = build(names, pos, edges, order);
    var n = names.length, INF = 1e9, d = names.map(function () { return INF; });
    d[0] = 0;
    var steps = [];
    var init = g.ops.slice();
    names.forEach(function (_, i) { init.push(['note', 'v' + i, i === 0 ? 'd=0' : 'd=inf']); });
    init.push(['tag', 'v0', 'done']);
    steps.push({ pl: 0, cl: 0, h: 380, say: 'Bellman-Ford handles negative edge weights. Start with distance 0 at the source ' + names[0] + ' and infinity everywhere else. Then repeat V - 1 = ' + (n - 1) + ' times: relax EVERY edge, in a fixed order. No heap needed.', csay: 'dist[] set to INF; dist[s] = 0.', ds: init });
    var prev = null;
    function fmt(x) { return x >= INF ? 'inf' : String(x); }
    var changedLast = false;
    for (var pass = 1; pass <= rounds; pass++) {
      var changed = false;
      var extra = pass === n;
      order.forEach(function (k) {
        var e = edges[k], u = e[0], v = e[1], w = e[2];
        var ops = [];
        if (prev !== null) ops.push(['euntag', 'v' + edges[prev][0], g.kindOf[prev], 'on']);
        ops.push(['etag', 'v' + u, g.kindOf[k], 'on']);
        var say, better = d[u] < INF && d[u] + w < d[v];
        if (d[u] >= INF) say = 'Pass ' + pass + ', edge ' + names[u] + ' to ' + names[v] + ' (' + w + '): ' + names[u] + ' is still unreachable (infinity), so nothing to relax.';
        else if (better) {
          say = 'Pass ' + pass + ', edge ' + names[u] + ' to ' + names[v] + ' (' + w + '): ' + d[u] + ' + ' + w + ' = ' + (d[u] + w) + ' < ' + fmt(d[v]) + '. Shorter route found: update ' + names[v] + '.';
          d[v] = d[u] + w; changed = true;
          ops.push(['note', 'v' + v, 'd=' + d[v]], ['hot', 'v' + v]);
          if (extra) ops.push(['tag', 'v' + v, 'bad']);
        } else say = 'Pass ' + pass + ', edge ' + names[u] + ' to ' + names[v] + ' (' + w + '): ' + d[u] + ' + ' + w + ' = ' + (d[u] + w) + ' is not better than ' + fmt(d[v]) + '. No change.';
        steps.push({ pl: extra ? 5 : 3, cl: extra ? 6 : 3, h: 380, say: (extra ? 'Extra pass: ' : '') + say, csay: better ? 'dist[' + names[v] + '] = ' + d[v] + ';' : 'No update.', ds: ops });
        prev = k;
      });
      var done = !cyc && !changed;
      steps.push({ pl: extra ? 6 : 1, cl: extra ? 6 : 1, h: 380, say: extra ? (changed ? 'Distances STILL improve after V - 1 passes. With no negative cycle that is impossible, so the graph has a negative cycle: shortest paths do not exist. Report it.' : 'The extra pass changed nothing: no negative cycle.') : (changed ? 'End of pass ' + pass + ': at least one distance improved.' : 'End of pass ' + pass + ': nothing changed, so we are done early. In general shortest paths use at most V - 1 edges, so V - 1 passes always suffice.'), csay: extra ? (changed ? 'Negative cycle detected.' : 'OK.') : 'Next pass.', ds: [] });
      if (done) break;
      changedLast = changed;
    }
    return steps;
  }

  var P4 = [[110, 130], [420, 60], [420, 210], [760, 130]];
  /* S, A, B, C: edges listed in an unlucky order so extra passes are needed */
  var e1 = [[1, 3, 2], [2, 1, -3], [0, 2, 5], [0, 1, 4]];
  var s1 = run(['S', 'A', 'B', 'C'], P4, e1, [0, 1, 2, 3], 4, false);

  var P4b = [[110, 140], [400, 50], [700, 140], [400, 220]];
  var e2 = [[0, 1, 1], [1, 2, 2], [2, 3, -4], [3, 1, 1]];
  var s2 = run(['S', 'A', 'B', 'C'], P4b, e2, [0, 1, 2, 3], 4, true);

  window.LESSON = {
    id: 'bellman-ford',
    mode: 'ds',
    title: 'Bellman-Ford and negative edges',
    lede:
      'Dijkstra needs non-negative weights. Bellman-Ford does not: it simply relaxes every edge V - 1 times. A shortest path never needs more than V - 1 edges, so after that many passes every distance is final. One extra pass reveals a negative cycle: if anything still improves, distances can fall forever and no shortest path exists. The price is O(V x E) time, much slower than Dijkstra, which is why you only use it when negative weights are possible (currency arbitrage, some scheduling constraints).',
    scenes: [
      { id: 'relax', title: 'Passes over all edges', blurb: 'Edges are processed in a fixed order; with an unlucky order it takes several passes for good distances to travel along a path.', trap: 'Stopping after one pass because it "looks done", or forgetting the early-exit test. Also guard against adding to infinity: in C skip the edge when dist[u] is INF, or INF + negative weight looks like a real distance.', pyCode: ['dist = [INF] * n; dist[s] = 0', 'for _ in range(n - 1):', '    for u, v, w in edges:', '        if dist[u] + w < dist[v]:', '            dist[v] = dist[u] + w', 'for u, v, w in edges:          # one more pass', '    if dist[u] + w < dist[v]:', '        return None            # negative cycle'], cCode: ['for (i = 0; i < n; i++) dist[i] = INF; dist[s] = 0;', 'for (int pass = 0; pass < n - 1; pass++)', '    for (int k = 0; k < m; k++) {', '        if (dist[e[k].u] != INF && dist[e[k].u] + e[k].w < dist[e[k].v])', '            dist[e[k].v] = dist[e[k].u] + e[k].w;', '    }', 'for (int k = 0; k < m; k++)    /* one more pass */', '    if (dist[e[k].u] + e[k].w < dist[e[k].v]) return 0;  /* negative cycle */'], predict: { q: 'A graph has 6 vertices. How many full passes over the edges are enough to finalise all shortest distances (no negative cycle)?', options: ['6 - 1 = 5', '6 x 6 = 36', '1'], answer: 0, why: 'A shortest path has at most V - 1 edges, and each pass extends correct distances by at least one more edge.' }, steps: s1 },
      { id: 'cycle', title: 'Detecting a negative cycle', blurb: 'The cycle A, B, C has total weight 2 - 4 + 1 = -1. Each lap makes distances smaller, forever.', trap: 'Treating a negative cycle as a normal answer. If the extra pass improves anything, shortest paths are undefined for the vertices that can reach the cycle. To list the cycle, follow parent pointers from a vertex that improved in the extra pass.', pyCode: ['dist = [INF] * n; dist[s] = 0', 'for _ in range(n - 1):', '    for u, v, w in edges:', '        if dist[u] + w < dist[v]:', '            dist[v] = dist[u] + w', 'for u, v, w in edges:          # one more pass', '    if dist[u] + w < dist[v]:', '        return None            # negative cycle'], cCode: ['for (i = 0; i < n; i++) dist[i] = INF; dist[s] = 0;', 'for (int pass = 0; pass < n - 1; pass++)', '    for (int k = 0; k < m; k++) {', '        if (dist[e[k].u] != INF && dist[e[k].u] + e[k].w < dist[e[k].v])', '            dist[e[k].v] = dist[e[k].u] + e[k].w;', '    }', 'for (int k = 0; k < m; k++)    /* one more pass */', '    if (dist[e[k].u] + e[k].w < dist[e[k].v]) return 0;  /* negative cycle */'], predict: { q: 'After V - 1 passes, one more pass still improves a distance. What does that prove?', options: ['The source is disconnected', 'There is a negative cycle reachable from the source', 'The edge order was wrong'], answer: 1, why: 'Without a negative cycle all distances are final after V - 1 passes, so a further improvement can only come from a cycle that keeps lowering the total.' }, steps: s2 },
    ],
    builtins: [
      ['float("inf")', 'Infinity sentinel in Python; inf + w stays inf.'],
      ['INT_MAX / 2 or a large constant', 'In C pick INF so INF + w cannot overflow, and skip edges from INF.'],
      ['for _ in range(n - 1)', 'The V - 1 passes loop.'],
      ['parent[v] = u', 'Record the predecessor to rebuild paths or the cycle.'],
      ['math.log(rate)', 'Currency arbitrage: take -log of rates so a profit cycle becomes a negative cycle.'],
    ],
  };
})();
